import json,os,hashlib,subprocess
import bb_ru45_review as api
R=api.ROOT;O=R/'results/ru45-emphasis';O.mkdir(parents=True,exist_ok=True);items=json.loads((R/'inputs/ru45-emphasis-input.json').read_text());api.save(O/'input.json',items);sources=[x['source'] for x in items];current=api.validate([{'source_id':x['source']['id'],'target':x['prior_target']} for x in items],sources);turns=[]
for phase in range(5):
 payload={'task':'Review and verify ONLY the restoration of these two authentic source italic spans. Preserve ALL reviewed Russian wording and punctuation exactly. The source italic née corresponds to Russian урождённая; source italic partie carrée (four-player company) corresponds to Russian нас четверо. Apply proposed targets in phase0, then independently compare CURRENT corrected whole paragraphs to English in later phases. Use PASS when current bytes already correct. Return JSON rows(source_id,target) and review(source_id,verdict PASS or CORRECTED,reason), every row exactly once in order. Do not rewrite prose.','source_rows':sources,'final_rows':current,'proposed_narrow_targets':[{'source_id':x['source']['id'],'target':x['expected_target']} for x in items],'phase':'SOURCE_ALIGNED_EMPHASIS_CORRECTION' if phase==0 else 'INDEPENDENT_SOURCE_COMPARISON'}
 result,meta=api.checked_call(api.SYSTEM,payload,O/f'phase{phase:02}',sources,True);changes=[{'source_id':a['source_id'],'before':a['target'],'after':b['target']} for a,b in zip(current,result['rows']) if a['target']!=b['target']];turns.append({'phase':phase,'api':meta,'review':result['review'],'corrections':changes});current=result['rows'];assert [x['target'] for x in current]==[x['expected_target'] for x in items],'UNSCOPED_EMPHASIS_CHANGE'
 if phase>=1 and not changes and all(x['verdict']=='PASS' for x in result['review']):break
else:raise RuntimeError('EMPHASIS_COMPARISON_NOT_STABLE')
api.save(O/'emphasis.verified.json',{'state':'ACTUAL2_EMPHASIS_RESTORATIONS_AND_SEPARATE_SOURCE_COMPARISON','run_id':os.environ.get('GITHUB_RUN_ID'),'rows':current,'turns':turns,'input_sha256':hashlib.sha256((O/'input.json').read_bytes()).hexdigest(),'book_release':False});subprocess.run(['git','add','results/ru45-emphasis'],cwd=R,check=True);subprocess.run(['git','commit','-m','Preserve actual source emphasis review and comparison'],cwd=R,check=True);subprocess.run(['git','push','origin','HEAD'],cwd=R,check=True)
